Args: input_data: Input parameters for the tool
Returns: ToolNameOutput: Result of the tool operation """ # Implementation here pass

api_integration_pattern.error_handling:

try:
    # API call
    result = call_api(endpoint, data)

    # Validate response
    if not result or "error" in result:
        return ErrorOutput(
            status="ERROR",
            message=result.get("error", "Unknown error"),
            data={}
        )

    # Process successful response
    return SuccessOutput(
        status="SUCCESS",
        data=result
    )

except requests.Timeout:
    return ErrorOutput(
        status="TIMEOUT",
        message="API request timed out",
        data={}
    )

except requests.RequestException as e:
    return ErrorOutput(
        status="ERROR",
        message=f"API request failed: {str(e)}",
        data={}
    )

except Exception as e:
    return ErrorOutput(
        status="ERROR",
        message=f"Unexpected error: {str(e)}",
        data={}
    )

tool_implementation_pattern.complete_tool_example:
""" Weather Forecast Tool for FleetOps Cold-Chain Logistics
This tool provides weather forecasts along truck routes by fetching truck data from the FleetOps backend API. """
from typing import List, Dict, Any, Optional from pydantic import BaseModel, Field from ibm_watsonx_orchestrate.agent_builder.tools import tool import requests import os from datetime import datetime, timezone
class WeatherSegment(BaseModel): """Weather information for a route segment""" location: str = Field(description="Location name or waypoint") coordinates: Dict[str, float] = Field(description="Latitude and longitude") condition: str = Field(description="Weather condition (Clear, Rain, Snow, etc.)") severity: str = Field(description="Severity level (CLEAR, MODERATE, SEVERE)") temperature: float = Field(description="Temperature in Fahrenheit") windSpeed: float = Field(description="Wind speed in mph") visibility: float = Field(description="Visibility in miles") estimatedDelay: int = Field(description="Estimated delay in minutes")
class WeatherForecastInput(BaseModel): """Input for weather forecast tool""" truck_id: str = Field(description="Truck identifier (e.g., TRUCK-001)") inject_weather_condition: Optional[str] = Field( None, description="Optional weather condition to inject for testing" )
class WeatherForecastOutput(BaseModel): """Output from weather forecast tool""" severeWeatherDetected: bool = Field(description="Whether severe weather was detected") overallWeatherRisk: int = Field(description="Overall risk score (0-100)") totalDelayMinutes: int = Field(description="Total estimated delay in minutes") segments: List[WeatherSegment] = Field(description="Weather data for each segment")
@tool def get_route_weather_forecast( input_data: WeatherForecastInput ) -> WeatherForecastOutput: """ Get weather forecast along a truck's route.
This tool fetches the truck's route from the FleetOps API and generates weather forecasts for each waypoint along the route.
Args: input_data: Input containing truck_id and optional weather injection
Returns: WeatherForecastOutput: Weather analysis with risk assessment """ # Get API configuration - must be provided by user api_url = os.environ.get('FLEETOPS_API_URL')
if not api_url: raise ValueError( "FLEETOPS_API_URL environment variable is not set. " "Please configure your FleetOps API endpoint before using this tool." )
timeout = 10
try: # Fetch truck data from API response = requests.get( f"{api_url}/api/trucks/{input_data.truck_id}", timeout=timeout ) response.raise_for_status() truck_data = response.json()
# Extract route information route = truck_data.get("route", {}) waypoints = route.get("waypoints", [])
if not waypoints: return WeatherForecastOutput( severeWeatherDetected=False, overallWeatherRisk=0, totalDelayMinutes=0, segments=[] )
# Generate weather forecast for each waypoint segments = [] total_delay = 0 max_risk = 0 severe_detected = False
for waypoint in waypoints: # Generate or fetch weather data weather = generate_weather_for_waypoint( waypoint, input_data.inject_weather_condition )
segment = WeatherSegment( location=waypoint.get("city", "Unknown"), coordinates={ "latitude": waypoint.get("latitude", 0.0), "longitude": waypoint.get("longitude", 0.0) }, condition=weather["condition"], severity=weather["severity"], temperature=weather["temperature"], windSpeed=weather["windSpeed"], visibility=weather["visibility"], estimatedDelay=weather["estimatedDelay"] )
segments.append(segment) total_delay += weather["estimatedDelay"]
if weather["severity"] == "SEVERE": severe_detected = True max_risk = max(max_risk, 80) elif weather["severity"] == "MODERATE": max_risk = max(max_risk, 50)
return WeatherForecastOutput( severeWeatherDetected=severe_detected, overallWeatherRisk=max_risk, totalDelayMinutes=total_delay, segments=segments )
except requests.Timeout: raise Exception(f"API request timed out after {timeout}s") except requests.RequestException as e: raise Exception(f"Failed to fetch truck data: {str(e)}") except Exception as e: raise Exception(f"Error generating weather forecast: {str(e)}")
def generate_weather_for_waypoint( waypoint: dict, forced_condition: Optional[str] = None ) -> dict: """ Generate weather data for a waypoint.
Args: waypoint: Waypoint information forced_condition: Optional forced weather condition
Returns: dict: Weather data """ # Implementation details... pass
